contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 role, address account) public {
        require(account != address(this), "test: account must be external");

        bytes32 admin = c.getRoleAdmin(role);
        bool adminIsSelf = (admin == role);

        if (adminIsSelf) {
            bool hadRoleBefore = c.hasRole(role, account);
            bool grantReverted;
            try c.grantRole(role, account) {
                grantReverted = false;
            } catch {
                grantReverted = true;
            }
            bool hasRoleAfterGrant = c.hasRole(role, account);

            bool renounceReverted;
            try c.renounceRole(role, account) {
                renounceReverted = false;
            } catch {
                renounceReverted = true;
            }
            bool hasRoleAfterRenounce = c.hasRole(role, account);

            assert(
                (!hadRoleBefore && !grantReverted) ? !hasRoleAfterGrant :
                (hadRoleBefore && !renounceReverted) ? !hasRoleAfterRenounce :
                true
            );
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

