contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 minDelay,
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay,
        bytes32 id,
        address account1,
        address account2
    ) public payable {
        require(true);

        // Snapshot the only observable value that can be read from c at the start.
        uint256 beforeMinDelay = c.getMinDelay();

        // Perform many mutating calls; none should change _minDelay because
        // updateDelay is guarded by msg.sender == address(this) and none of these
        // calls originate from c itself.
        c.schedule(target, value, data, predecessor, salt, delay);
        c.grantRole(0x00, address(this));
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(this));
        c.revokeRole(c.PROPOSER_ROLE(), address(this));
        c.renounceRole(c.EXECUTOR_ROLE(), address(this));
        c.cancel(id);
        c.execute(target, value, data, predecessor, salt);

        uint256 afterMinDelay = c.getMinDelay();

        assert(afterMinDelay == beforeMinDelay);
    }

    receive() external payable {}
}

